USE aiims_connect;
CREATE TABLE IF NOT EXISTS branch(Branch_ID INT AUTO_INCREMENT PRIMARY KEY,Branch_Name VARCHAR(100) NOT NULL UNIQUE,City VARCHAR(80) NOT NULL,Is_Main BOOLEAN DEFAULT FALSE,Created_At TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS department(Dept_ID INT AUTO_INCREMENT PRIMARY KEY,Branch_ID INT NOT NULL,Dept_Name VARCHAR(100) NOT NULL,FOREIGN KEY(Branch_ID) REFERENCES branch(Branch_ID),UNIQUE(Branch_ID,Dept_Name)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ward(Ward_ID INT AUTO_INCREMENT PRIMARY KEY,Branch_ID INT NOT NULL,Ward_Name VARCHAR(100) NOT NULL,Ward_Type ENUM('General','ICU','Emergency','Private') DEFAULT 'General',Total_Beds INT NOT NULL,Available_Beds INT NOT NULL,Daily_Rate DECIMAL(10,2) DEFAULT 0,FOREIGN KEY(Branch_ID) REFERENCES branch(Branch_ID),UNIQUE(Branch_ID,Ward_Name),CHECK(Total_Beds>0 AND Available_Beds>=0 AND Available_Beds<=Total_Beds),INDEX idx_ward_branch_type(Branch_ID,Ward_Type)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS login(Login_ID INT AUTO_INCREMENT PRIMARY KEY,Username VARCHAR(60) NOT NULL UNIQUE,Password_Hash VARCHAR(100) NOT NULL,Role ENUM('chain_admin','branch_admin','doctor','receptionist','patient') NOT NULL,Is_Active BOOLEAN DEFAULT TRUE,Created_At TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS staff(Staff_ID INT AUTO_INCREMENT PRIMARY KEY,Login_ID INT NOT NULL UNIQUE,Branch_ID INT NULL,Name VARCHAR(120) NOT NULL,DOB DATE NULL,Phone VARCHAR(20),Staff_Type ENUM('Doctor','Receptionist','Admin') NOT NULL,FOREIGN KEY(Login_ID) REFERENCES login(Login_ID),FOREIGN KEY(Branch_ID) REFERENCES branch(Branch_ID),INDEX idx_staff_branch_type(Branch_ID,Staff_Type)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS doctor(Staff_ID INT PRIMARY KEY,Dept_ID INT NOT NULL,Specialization VARCHAR(100) NOT NULL,Consultation_Fee DECIMAL(10,2) DEFAULT 0,Qualification VARCHAR(150),FOREIGN KEY(Staff_ID) REFERENCES staff(Staff_ID) ON DELETE CASCADE,FOREIGN KEY(Dept_ID) REFERENCES department(Dept_ID),CHECK(Consultation_Fee>=0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS receptionist(Staff_ID INT PRIMARY KEY,Counter_No VARCHAR(20),FOREIGN KEY(Staff_ID) REFERENCES staff(Staff_ID) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS admin_staff(Staff_ID INT PRIMARY KEY,Access_Level ENUM('chain_admin','branch_admin') NOT NULL,FOREIGN KEY(Staff_ID) REFERENCES staff(Staff_ID) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS patient(UHID VARCHAR(24) PRIMARY KEY,Login_ID INT UNIQUE NULL,Name VARCHAR(120) NOT NULL,DOB DATE NOT NULL,Gender ENUM('Male','Female','Other') NULL,Address VARCHAR(255),Phone VARCHAR(20),Blood_Group ENUM('A+','A-','B+','B-','AB+','AB-','O+','O-') NULL,Created_At TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(Login_ID) REFERENCES login(Login_ID)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS appointment(Appt_ID BIGINT AUTO_INCREMENT PRIMARY KEY,UHID VARCHAR(24) NOT NULL,Staff_ID INT NOT NULL,Branch_ID INT NOT NULL,Appt_Date DATE NOT NULL,Time_Slot TIME NOT NULL,Token_No INT NOT NULL,Status ENUM('Booked','Cancelled','Completed','No_Show') DEFAULT 'Booked',Active_Flag TINYINT GENERATED ALWAYS AS(CASE WHEN Status IN('Booked','Completed') THEN 1 ELSE NULL END) STORED,Created_At TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(UHID) REFERENCES patient(UHID),FOREIGN KEY(Staff_ID) REFERENCES staff(Staff_ID),FOREIGN KEY(Branch_ID) REFERENCES branch(Branch_ID),UNIQUE uq_doctor_slot(Staff_ID,Appt_Date,Time_Slot,Active_Flag),UNIQUE uq_branch_token(Branch_ID,Appt_Date,Token_No),INDEX idx_appt_uhid_date(UHID,Appt_Date),INDEX idx_appt_branch_date(Branch_ID,Appt_Date)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS prescription(Prescription_ID BIGINT AUTO_INCREMENT PRIMARY KEY,Appt_ID BIGINT NOT NULL,Medicine_Name VARCHAR(150) NOT NULL,Dosage VARCHAR(100) NOT NULL,Notes TEXT,Created_At TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(Appt_ID) REFERENCES appointment(Appt_ID),INDEX idx_prescription_appt(Appt_ID)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS admission(Admission_ID BIGINT AUTO_INCREMENT PRIMARY KEY,UHID VARCHAR(24) NOT NULL,Ward_ID INT NOT NULL,Admitting_Staff_ID INT NULL,Admit_Date DATE NOT NULL,Discharge_Date DATE NULL,Attendant_Name VARCHAR(120),Attendant_Phone VARCHAR(20),Status ENUM('Active','Discharged') DEFAULT 'Active',Created_At TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(UHID) REFERENCES patient(UHID),FOREIGN KEY(Ward_ID) REFERENCES ward(Ward_ID),FOREIGN KEY(Admitting_Staff_ID) REFERENCES staff(Staff_ID),CHECK(Discharge_Date IS NULL OR Discharge_Date>=Admit_Date),INDEX idx_admission_uhid(UHID),INDEX idx_admission_status(Status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS billing(Bill_ID BIGINT AUTO_INCREMENT PRIMARY KEY,Admission_ID BIGINT NOT NULL UNIQUE,Consultation_Fee DECIMAL(10,2) DEFAULT 0,Room_Charges DECIMAL(10,2) DEFAULT 0,Medicine_Charges DECIMAL(10,2) DEFAULT 0,Total DECIMAL(12,2) GENERATED ALWAYS AS(Consultation_Fee+Room_Charges+Medicine_Charges) STORED,Status ENUM('Unpaid','Paid','Partially_Paid','Waived') DEFAULT 'Unpaid',Created_At TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(Admission_ID) REFERENCES admission(Admission_ID),CHECK(Consultation_Fee>=0 AND Room_Charges>=0 AND Medicine_Charges>=0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS referral(Referral_ID BIGINT AUTO_INCREMENT PRIMARY KEY,UHID VARCHAR(24) NOT NULL,From_Branch_ID INT NOT NULL,To_Branch_ID INT NOT NULL,Created_By_Staff_ID INT NOT NULL,Destination_Doctor_ID INT NULL,Appt_ID BIGINT NULL UNIQUE,Reason VARCHAR(500) NOT NULL,Status ENUM('Pending','Accepted','Rejected','Completed') DEFAULT 'Pending',Created_At TIMESTAMP DEFAULT CURRENT_TIMESTAMP,Updated_At TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(UHID) REFERENCES patient(UHID),FOREIGN KEY(From_Branch_ID) REFERENCES branch(Branch_ID),FOREIGN KEY(To_Branch_ID) REFERENCES branch(Branch_ID),FOREIGN KEY(Created_By_Staff_ID) REFERENCES staff(Staff_ID),FOREIGN KEY(Destination_Doctor_ID) REFERENCES doctor(Staff_ID),FOREIGN KEY(Appt_ID) REFERENCES appointment(Appt_ID),CHECK(From_Branch_ID<>To_Branch_ID),INDEX idx_referral_status(Status,To_Branch_ID)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_log(Log_ID BIGINT AUTO_INCREMENT PRIMARY KEY,Login_ID INT NULL,Action VARCHAR(40) NOT NULL,Table_Affected VARCHAR(64) NOT NULL,Record_ID VARCHAR(64) NOT NULL,Logged_At TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(Login_ID) REFERENCES login(Login_ID) ON DELETE SET NULL,INDEX idx_audit_table_time(Table_Affected,Logged_At)) ENGINE=InnoDB;
